#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/drivers/i2c.h>
#include <zephyr/drivers/i2c_rtio.h>
#include <zephyr/rtio/rtio.h>
#include <zephyr/logging/log.h>
#include <zephyr/sys/atomic.h>
#include <string.h>

LOG_MODULE_REGISTER(i2c_rtio, CONFIG_I2C_LOG_LEVEL);

#ifndef CONFIG_I2C_RTIO_MAX_MSGS_PER_REQUEST
#define CONFIG_I2C_RTIO_MAX_MSGS_PER_REQUEST 4
#endif
#ifndef CONFIG_I2C_RTIO_COPY_POOL_BUFFER_SIZE
#define CONFIG_I2C_RTIO_COPY_POOL_BUFFER_SIZE 128
#endif
#ifndef CONFIG_I2C_RTIO_COPY_POOL_SIZE
#define CONFIG_I2C_RTIO_COPY_POOL_SIZE 4
#endif
#ifndef CONFIG_I2C_RTIO_INIT_PRIORITY
#define CONFIG_I2C_RTIO_INIT_PRIORITY 50
#endif

#ifdef CONFIG_I2C_RTIO_COPY_POOL_SIZE
K_MEM_SLAB_DEFINE(i2c_rtio_copy_slab, CONFIG_I2C_RTIO_COPY_POOL_BUFFER_SIZE,
                  CONFIG_I2C_RTIO_COPY_POOL_SIZE, 4);
#endif

struct i2c_rtio_req {
    struct i2c_msg *msgs;
    uint8_t num_msgs;
    uint16_t addr;
#ifdef CONFIG_I2C_RTIO_COPY_POOL_SIZE
    void *copy_bufs[CONFIG_I2C_RTIO_MAX_MSGS_PER_REQUEST];
    void *orig_bufs[CONFIG_I2C_RTIO_MAX_MSGS_PER_REQUEST];
#endif
};

struct i2c_rtio_data {
    struct k_work_delayable work;
    struct rtio_iodev iodev;
    const struct device *i2c_dev;
};

struct i2c_rtio_config {
    const struct device *i2c_controller;
};

static void i2c_rtio_work_handler(struct k_work *work)
{
    struct k_work_delayable *dwork = k_work_delayable_from_work(work);
    struct i2c_rtio_data *data = CONTAINER_OF(dwork, struct i2c_rtio_data, work);
    struct rtio_sqe *sqe;
    int ret;

    while ((sqe = rtio_sqe_peek_next(&data->iodev)) != NULL) {
        struct i2c_rtio_req *req = (struct i2c_rtio_req *)rtio_sqe_get_iodev_data(sqe);

        ret = i2c_transfer(data->i2c_dev, req->msgs, req->num_msgs, req->addr);

#ifdef CONFIG_I2C_RTIO_COPY_POOL_SIZE
        for (int i = 0; i < req->num_msgs; i++) {
            if (req->copy_bufs[i] != NULL) {
                if ((req->msgs[i].flags & I2C_MSG_RW_BIT) == I2C_MSG_READ) {
                    memcpy(req->orig_bufs[i], req->copy_bufs[i], req->msgs[i].len);
                }
                k_mem_slab_free(&i2c_rtio_copy_slab, req->copy_bufs[i]);
            }
        }
#endif

        rtio_sqe_complete(sqe, ret);
    }
}

static int i2c_rtio_submit(const struct device *dev, struct rtio_sqe *sqe)
{
    struct i2c_rtio_data *data = dev->data;
    struct i2c_rtio_req *req = (struct i2c_rtio_req *)rtio_sqe_get_iodev_data(sqe);
    int ret = 0;

    req->addr = rtio_sqe_get_iodev_data_flags(sqe);
    req->num_msgs = rtio_sqe_get_iodev_data_len(sqe);
    req->msgs = (struct i2c_msg *)rtio_sqe_get_mdata(sqe);

    if (req->num_msgs == 0 || req->msgs == NULL) {
        LOG_ERR("Invalid I2C RTIO request: no messages or null message pointer");
        return -EINVAL;
    }

    if (req->num_msgs > CONFIG_I2C_RTIO_MAX_MSGS_PER_REQUEST) {
        LOG_ERR("Too many I2C messages in request (%d > %d)",
                req->num_msgs, CONFIG_I2C_RTIO_MAX_MSGS_PER_REQUEST);
        return -EINVAL;
    }

#ifdef CONFIG_I2C_RTIO_COPY_POOL_SIZE
    for (int i = 0; i < req->num_msgs; i++) {
        req->copy_bufs[i] = NULL;
        req->orig_bufs[i] = NULL;
    }

    for (int i = 0; i < req->num_msgs; i++) {
        struct i2c_msg *msg = &req->msgs[i];
        void *user_buf_base = rtio_sqe_get_buf(sqe);
        void *current_user_buf = NULL;

        if (msg->buf != NULL) {
            size_t user_buf_offset = (uintptr_t)msg->buf - (uintptr_t)user_buf_base;
            current_user_buf = (void *)((uintptr_t)user_buf_base + user_buf_offset);
        }

        bool needs_copy = ((msg->flags & I2C_MSG_RW_BIT) == I2C_MSG_READ) ||
                          (current_user_buf != NULL && !rtio_is_dma_safe(current_user_buf));

        if (msg->len == 0) {
            continue;
        }

        if (needs_copy) {
            if (msg->len > CONFIG_I2C_RTIO_COPY_POOL_BUFFER_SIZE) {
                LOG_ERR("I2C message buffer too large for copy pool (%zu > %u)",
                        msg->len, CONFIG_I2C_RTIO_COPY_POOL_BUFFER_SIZE);
                ret = -EINVAL;
                goto cleanup_copy_bufs;
            }

            ret = k_mem_slab_alloc(&i2c_rtio_copy_slab, &req->copy_bufs[i], K_NO_WAIT);
            if (ret != 0) {
                LOG_ERR("Failed to allocate from I2C RTIO copy pool (%d)", ret);
                ret = -ENOMEM;
                goto cleanup_copy_bufs;
            }

            if ((msg->flags & I2C_MSG_RW_BIT) == I2C_MSG_WRITE) {
                if (current_user_buf == NULL) {
                    LOG_ERR("Write message has NULL user buffer but needs copy");
                    ret = -EINVAL;
                    goto cleanup_copy_bufs;
                }
                memcpy(req->copy_bufs[i], current_user_buf, msg->len);
            }
            req->orig_bufs[i] = current_user_buf;
            msg->buf = req->copy_bufs[i];
        }
    }
#endif

    rtio_sqe_enqueue(&data->iodev, sqe);
    k_work_schedule(&data->work, K_NO_WAIT);

    return 0;

#ifdef CONFIG_I2C_RTIO_COPY_POOL_SIZE
cleanup_copy_bufs:
    for (int i = 0; i < req->num_msgs; i++) {
        if (req->copy_bufs[i] != NULL) {
            k_mem_slab_free(&i2c_rtio_copy_slab, req->copy_bufs[i]);
        }
    }
    return ret;
#endif
}

static int i2c_rtio_iodev_init(const struct device *dev)
{
    struct i2c_rtio_data *data = dev->data;

    k_work_init_delayable(&data->work, i2c_rtio_work_handler);
    rtio_iodev_init(&data->iodev, dev);

    return 0;
}

static const struct rtio_iodev_api i2c_rtio_iodev_api = {
    .submit = i2c_rtio_submit,
    .iodev_init = i2c_rtio_iodev_init,
};

static int i2c_rtio_init(const struct device *dev)
{
    struct i2c_rtio_data *data = dev->data;
    const struct i2c_rtio_config *config = dev->config;

    data->i2c_dev = config->i2c_controller;
    if (!device_is_ready(data->i2c_dev)) {
        LOG_ERR("I2C controller device not ready: %s", config->i2c_controller->name);
        return -ENODEV;
    }

    return i2c_rtio_iodev_init(dev);
}

#define I2C_RTIO_INIT(n)                                                                           \
    static struct i2c_rtio_data i2c_rtio_data_##n;                                                 \
    static const struct i2c_rtio_config i2c_rtio_config_##n = {                                    \
        .i2c_controller = DEVICE_DT_GET(DT_INST_PHANDLE(n, i2c_controller)),                       \
    };                                                                                             \
    DEVICE_DT_INST_DEFINE(n, i2c_rtio_init, NULL, &i2c_rtio_data_##n, &i2c_rtio_config_##n,        \
                          POST_KERNEL, CONFIG_I2C_RTIO_INIT_PRIORITY, &i2c_rtio_iodev_api);

DT_INST_FOREACH_STATUS_OKAY(I2C_RTIO_INIT)
